//! Generated source emission for the portable engine.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::path::Path;

use crate::model::{
    read_file, FunctionOrigin, FunctionReport, PatchError, PatchMismatch, RawFunction,
    SelectedFunctions,
};
use crate::transform::{state_field_name, state_field_type, Edit, PatchSession};

/// Generated file header naming the command that regenerates it.
const GENERATED_BY: &str = "Generated by `cargo run -p mathtex-web2c-import --bin patch_engine`.";

/// Lints the translated functions trigger, allowed in every `functions/` module.
const FUNCTIONS_ALLOW: &str = "#![allow(dead_code, non_camel_case_types, non_snake_case, unused_assignments, unused_mut, unused_variables)]";

/// Extracts the XeTeX startup primitive block of `mainbody` as the `init_xetex_startup_primitives` method.
pub(crate) fn translated_xetex_startup_primitives(
    functions: &BTreeMap<String, RawFunction>,
    translated_functions: &BTreeSet<String>,
    globals: &BTreeMap<String, String>,
    session: &mut PatchSession,
) -> Result<String, PatchError> {
    let mainbody = functions
        .get("mainbody")
        .ok_or(PatchError::MissingTranslatedBlock {
            function: "mainbody",
        })?
        .patch(translated_functions, globals, session);
    let condition_end = find_marker_end(
        &mainbody,
        "&& self.state.formatident as i64 == 66713 as i64",
    )
    .ok_or(PatchError::MissingTranslatedBlock {
        function: "mainbody:XeTeX startup condition",
    })?;
    let block_start = mainbody[condition_end..]
        .find('{')
        .map(|offset| condition_end + offset + 1)
        .ok_or(PatchError::MissingTranslatedBlock {
            function: "mainbody:XeTeX startup block start",
        })?;
    let block_end_marker = "if self.state.nonewcontrolsequence == 0";
    let block_end = find_ignoring_whitespace(&mainbody[block_start..], block_end_marker)
        .map(|offset| block_start + offset)
        .ok_or(PatchError::MissingTranslatedBlock {
            function: "mainbody:XeTeX startup block end",
        })?;
    let primitive_block =
        trim_trailing_standalone_brace_lines(mainbody[block_start..block_end].trim());
    let mut source = String::new();
    writeln!(
        source,
        "    unsafe fn init_xetex_startup_primitives(&mut self) {{"
    )
    .expect("write to String");
    for line in primitive_block.lines() {
        writeln!(source, "        {line}").expect("write to String");
    }
    writeln!(source, "    }}\n").expect("write to String");
    Ok(source)
}

fn trim_trailing_standalone_brace_lines(source: &str) -> String {
    let mut lines = source.lines().collect::<Vec<_>>();
    while matches!(lines.last(), Some(line) if line.trim() == "}") {
        lines.pop();
    }
    lines.join("\n")
}

fn find_marker_end(source: &str, marker: &str) -> Option<usize> {
    let start = find_ignoring_whitespace(source, marker)?;
    matched_end_ignoring_whitespace(&source[start..], marker).map(|length| start + length)
}

/// `mainbody` is reformatted by `prettyplease`, so markers can't be matched as literal substrings.
fn find_ignoring_whitespace(haystack: &str, needle: &str) -> Option<usize> {
    (0..=haystack.len())
        .find(|&start| matched_end_ignoring_whitespace(&haystack[start..], needle).is_some())
}

fn matched_end_ignoring_whitespace(text: &str, needle: &str) -> Option<usize> {
    let tb = text.as_bytes();
    let nb = needle.as_bytes();
    let is_word = |b: u8| b.is_ascii_alphanumeric() || b == b'_';
    let mut ti = 0;
    let mut ni = 0;
    let mut prev_needle: Option<u8> = None;
    // The match must start at text[0], callers scan every position, so indentation is not skipped.
    while ni < nb.len() {
        if nb[ni].is_ascii_whitespace() {
            while ni < nb.len() && nb[ni].is_ascii_whitespace() {
                ni += 1;
            }
            while ti < tb.len() && tb[ti].is_ascii_whitespace() {
                ti += 1;
            }
            prev_needle = Some(b' ');
            continue;
        }
        // Skip whitespace in text only at token boundaries, never within identifier or number runs.
        if let Some(prev) = prev_needle {
            let at_token_boundary = !is_word(nb[ni]) || !is_word(prev);
            if at_token_boundary {
                while ti < tb.len() && tb[ti].is_ascii_whitespace() {
                    ti += 1;
                }
            }
        }
        if ti >= tb.len() || tb[ti] != nb[ni] {
            return None;
        }
        prev_needle = Some(nb[ni]);
        ti += 1;
        ni += 1;
    }
    Some(ti)
}

pub(crate) struct FunctionsFile {
    pub(crate) file_name: String,
    pub(crate) contents: String,
}

pub(crate) struct FunctionsSplit {
    pub(crate) files: Vec<FunctionsFile>,
    pub(crate) mod_rs: String,
}

/// Splits function blocks into per letter partial `impl` modules without rewriting their bytes.
pub(crate) fn functions_split(items: &[String]) -> FunctionsSplit {
    let mut groups: BTreeMap<char, Vec<&String>> = BTreeMap::new();
    for item in items {
        let name = function_block_name(item)
            .expect("every emitted item is a `pub(crate) unsafe fn <name>` block");
        groups.entry(group_key(&name)).or_default().push(item);
    }

    let mut files = Vec::new();
    let mut module_names = Vec::new();
    for (key, group_items) in &groups {
        let module_name = group_module_name(*key);
        module_names.push(module_name.clone());
        let mut contents = String::new();
        writeln!(
            contents,
            "//! XeTeX engine functions, group `{module_name}`.\n//! {GENERATED_BY}\n"
        )
        .expect("write to String");
        writeln!(contents, "{FUNCTIONS_ALLOW}\n").expect("write to String");
        writeln!(contents, "use crate::runtime::*;\n").expect("write to String");
        writeln!(
            contents,
            "impl<'resources> PortableTexEngine<'resources> {{\n"
        )
        .expect("write to String");
        for item in group_items {
            contents.push_str(item);
            contents.push('\n');
        }
        contents.push_str("}\n");
        files.push(FunctionsFile {
            file_name: format!("{module_name}.rs"),
            contents,
        });
    }

    let mut mod_rs = String::new();
    writeln!(
        mod_rs,
        "//! XeTeX engine functions, split into per letter partial `impl` blocks.\n//! {GENERATED_BY}\n"
    )
    .expect("write to String");
    for module_name in &module_names {
        writeln!(mod_rs, "mod {module_name};").expect("write to String");
    }
    FunctionsSplit { files, mod_rs }
}

fn function_block_name(item: &str) -> Option<String> {
    const PREFIX: &str = "pub(crate) unsafe fn ";
    let start = item.find(PREFIX)? + PREFIX.len();
    let rest = &item[start..];
    let end = rest
        .find(|character: char| character == '(' || character == '<' || character.is_whitespace())
        .unwrap_or(rest.len());
    Some(rest[..end].to_string())
}

fn group_key(name: &str) -> char {
    match name.chars().next() {
        Some(c) if c.is_ascii_alphabetic() => c.to_ascii_lowercase(),
        _ => '_',
    }
}

fn group_module_name(key: char) -> String {
    if key == '_' {
        "other".to_string()
    } else {
        key.to_string()
    }
}

/// Pool strings the runtime names, looked up by content so their numbers follow the tangled pool.
const POOL_STRING_CONSTANTS: &[(&str, &str, &str)] = &[
    (
        "POOL_EMPTY_STRING",
        "",
        "The empty string, an absent file extension.",
    ),
    (
        "POOL_TEX_EXTENSION",
        ".tex",
        "The `.tex` extension `\\openout` supplies.",
    ),
    (
        "POOL_BUFFER_SIZE",
        "buffer size",
        "The capacity `overflow` names for a line longer than the buffer.",
    ),
    (
        "POOL_PRUNING",
        "pruning",
        "The `confusion` label of `prune_page_top`.",
    ),
    (
        "POOL_ERROR_PREFIX",
        "! ",
        "The prefix `print_err` starts every error message with.",
    ),
    (
        "POOL_MATH_SPACING",
        "0234000122*4000133**3**344*0400400*000000234000111*1111112341011",
        "The inter atom spacing table `magic_offset` indexes.",
    ),
];

/// Number of the first multi character pool string, the 65536 single character strings come first.
const FIRST_POOL_STRING: usize = 65_536;

/// Emits `pub(crate) const` string numbers for [`POOL_STRING_CONSTANTS`] from the tangled pool text.
pub(crate) fn pool_string_constants(pool: &str) -> Result<String, PatchError> {
    // Each pool line is a two digit length then the text, until the `*` checksum line.
    let strings = pool
        .lines()
        .take_while(|line| !line.starts_with('*'))
        .map(|line| line.get(2..).unwrap_or(""))
        .collect::<Vec<_>>();
    let mut constants = String::new();
    let mut missing = Vec::new();
    for (name, text, doc) in POOL_STRING_CONSTANTS {
        match strings.iter().position(|string| string == text) {
            Some(index) => writeln!(
                constants,
                "/// {doc}\npub(crate) const {name}: strnumber = {};",
                FIRST_POOL_STRING + index
            )
            .expect("write to String"),
            None => missing.push(PatchMismatch {
                function: "runtime prelude".to_string(),
                detail: format!("pool string {text:?} for {name} is not in xetex.pool"),
            }),
        }
    }
    if missing.is_empty() {
        Ok(constants)
    } else {
        Err(PatchError::PatchMismatches(missing))
    }
}

pub(crate) fn runtime_source(
    globals: &BTreeMap<String, String>,
    referenced_globals: &BTreeSet<String>,
    xetex_startup_primitives: &str,
    pool_constants: &str,
    flow_triggers: &crate::flow::FlowTriggers,
    session: &mut PatchSession,
) -> Result<String, PatchError> {
    let mut source = include_str!("../runtime/prelude.rs.in").to_string();
    fill_placeholder(&mut source, "{pool_string_constants}\n", pool_constants)?;

    let mut state_fields = String::new();
    for name in referenced_globals {
        if name == "mem" {
            continue;
        }
        let Some(ty) = globals.get(name) else {
            continue;
        };
        // zeqtb and hash use PagedView for paged sparse backing, offset calls go through the pager.
        let field = state_field_name(name);
        let ty_str = match field {
            "zeqtb" => "PagedView<memoryword>".to_string(),
            "hash" => "PagedView<twohalves>".to_string(),
            _ => state_field_type(ty),
        };
        writeln!(state_fields, "    pub {field}: {ty_str},").expect("write to String");
    }
    fill_placeholder(&mut source, "{state_fields}", &state_fields)?;
    fill_placeholder(
        &mut source,
        "{xetex_startup_primitives}",
        xetex_startup_primitives,
    )?;
    if let Some((head, tail)) =
        source.split_once("impl<'resources> PortableTexEngine<'resources> {\n")
    {
        let mut tail = tail.to_string();
        tail = tail.replace("(&mut self, ", "(");
        tail = tail.replace("(&mut self)", "()");
        tail = tail.replace("        &mut self,\n", "");
        tail = tail.replace("self.host_", "Self::host_");
        source = format!("{head}impl<'resources> PortableTexEngine<'resources> {{\n{tail}");
    }
    // Restore the `&mut self` receiver the tail rewrite stripped from the startup method.
    session.edit(
        &mut source,
        "runtime prelude",
        &Edit {
            anchor: "unsafe fn init_xetex_startup_primitives() -> EngineFlow<()> {",
            replacement: "unsafe fn init_xetex_startup_primitives(&mut self) -> EngineFlow<()> {",
            count: 1,
        },
    );

    // Rewrites named prelude bridges to propagate abort via ?, catch points are handwritten and excluded.
    Ok(crate::flow::rewrite_named_functions(
        source,
        crate::flow::PRELUDE_BRIDGE_FUNCTIONS,
        flow_triggers,
    ))
}

/// Fills the runtime's build fingerprint with a SHA-256 prefix of every generated source.
pub(crate) fn fill_build_fingerprint(
    runtime: &mut String,
    functions: &FunctionsSplit,
) -> Result<(), PatchError> {
    use sha2::{Digest, Sha256};
    let mut hasher = Sha256::new();
    // The runtime still holds the placeholder, so the digest never depends on its own value.
    for (name, contents) in [("runtime.rs", runtime.as_str()), ("lib.rs", lib_source())]
        .into_iter()
        .chain([("functions/mod.rs", functions.mod_rs.as_str())])
        .chain(
            functions
                .files
                .iter()
                .map(|file| (file.file_name.as_str(), file.contents.as_str())),
        )
    {
        hasher.update(name.as_bytes());
        hasher.update((contents.len() as u64).to_le_bytes());
        hasher.update(contents.as_bytes());
    }
    let digest = hasher.finalize();
    let mut prefix = [0u8; 8];
    prefix.copy_from_slice(&digest[..8]);
    let fingerprint = format!("0x{:016x}", u64::from_le_bytes(prefix));
    fill_placeholder(runtime, "{build_fingerprint}", &fingerprint)
}

fn fill_placeholder(source: &mut String, placeholder: &str, value: &str) -> Result<(), PatchError> {
    let found = source.matches(placeholder).count();
    if found != 1 {
        return Err(PatchError::PatchMismatches(vec![PatchMismatch {
            function: "runtime prelude".to_string(),
            detail: format!("placeholder {placeholder} found {found} times, expected 1"),
        }]));
    }
    *source = source.replace(placeholder, value);
    Ok(())
}

/// Generated crate manifest, keeping the package version of the existing one at `path`.
pub(crate) fn cargo_source(path: &Path) -> Result<String, PatchError> {
    let existing = read_file(path)?;
    let version = existing
        .lines()
        .find_map(|line| {
            let value = line
                .strip_prefix("version")?
                .trim_start()
                .strip_prefix('=')?;
            value.trim().strip_prefix('"')?.strip_suffix('"')
        })
        .ok_or_else(|| PatchError::MissingCrateVersion {
            path: path.to_path_buf(),
        })?;
    Ok(format!(
        r#"[package]
name = "mathtex-portable-engine-generated"
version = "{version}"
edition = "2021"
description = "Machine generated portable TeX engine core for mathtex, translated from the TeX, eTeX and XeTeX sources"
repository = "https://github.com/gabriel-nsiqueira/mathtex"
license-file = "LICENSE"

[lib]
path = "src/lib.rs"

[dependencies]
"#
    ))
}

pub(crate) fn lib_source() -> &'static str {
    r#"//! Auto-patched portable engine source from Web2C/C2Rust bootstrap output.

// Clippy lints the translated functions trigger, other lints stay on for the hand written runtime.
#![allow(
    clippy::assign_op_pattern,
    clippy::collapsible_if,
    clippy::collapsible_match,
    clippy::if_same_then_else,
    clippy::manual_range_patterns,
    clippy::needless_return,
    clippy::precedence,
    clippy::single_match,
    clippy::toplevel_ref_arg,
    clippy::unit_arg,
    clippy::unnecessary_cast,
    clippy::wildcard_in_or_patterns
)]

pub mod runtime;
// XeTeX engine functions, split into per letter partial `impl` blocks under `functions/`.
pub(crate) mod functions;

pub use runtime::memory_word_bytes;
pub use runtime::{
    EmptyFontPlatform, EmptyPlatform, EmptyResourceProvider, FontPlatform, FormatImageError,
    GlyphAssembly, PortableClock, PortableFontHandle, PortableFontMetrics, PortableFormatImage,
    PortableError, PortableErrorKind, PortableGlyphBounds, PortableHostBox, PortableHostBoxGlyph,
    PortableHostBoxRequest,
    PortableHostBoxRule, PortableHostBoxRun, PortableHostBoxStyle, PortableLinebreakRequest,
    PortableMathAssemblyPart, PortableMathKernCorner, PortableMathVariant, PortableNativeGlyph,
    PortableNativeGlyphMetrics, PortableNativeTextMetrics, PortableNoadKind, PortableNodeHandle,
    PortableNodeKind, PortableNodeSnapshot, PortablePlatform, PortableResourceRequestRecord,
    PortableSourceSpan, PortableTexEngine, ResourceKind, ResourceProvider, ResourceRequest,
    FILE_SIZE_PROBE_MODE, SANDBOX_OP_BUDGET,
};
"#
}

/// Tab separated report: summary counts, then one row per emitted function with its upstream hash.
pub(crate) fn report_source(functions: &[FunctionReport], selected: &SelectedFunctions) -> String {
    let mut report = String::from("kind\tsymbol\tclass\tupstream_hash\texternal_boundaries\n");
    writeln!(report, "summary\tfunctions\t{}", functions.len()).expect("write to String");
    for origin in FunctionOrigin::ALL {
        let count = functions
            .iter()
            .filter(|function| function.origin == origin)
            .count();
        writeln!(report, "summary\t{}\t{count}", origin.as_str()).expect("write to String");
    }
    let boundaries = [
        ("AdaptedNativeIo", &selected.boundary_adapted_native_io),
        ("StrippedOutput", &selected.boundary_stripped_output),
        (
            "StrippedNativeFontAssembly",
            &selected.boundary_stripped_native_font_assembly,
        ),
    ];
    for (class, symbols) in boundaries {
        writeln!(report, "summary\tboundary_{class}\t{}", symbols.len()).expect("write to String");
    }
    for function in functions {
        let external_boundaries = if function.external_boundaries.is_empty() {
            "Clean".to_string()
        } else {
            function.external_boundaries.join(",")
        };
        writeln!(
            report,
            "function\t{}\t{}\t{:016x}\t{external_boundaries}",
            function.symbol,
            function.origin.as_str(),
            function.upstream_hash,
        )
        .expect("write to String");
    }
    for (class, symbols) in boundaries {
        for symbol in symbols {
            writeln!(
                report,
                "boundary\t{symbol}\t{class}\t-\tAllowedManualAdapter"
            )
            .expect("write to String");
        }
    }
    for symbol in &selected.prelude_defined {
        writeln!(report, "prelude\t{symbol}\tHandwritten\t-\t-").expect("write to String");
    }
    for skipped in &selected.skipped {
        writeln!(
            report,
            "skipped\t{}\t{}\t-\t-",
            skipped.symbol, skipped.reason
        )
        .expect("write to String");
    }
    report
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn whitespace_insensitive_match_finds_contiguous_marker() {
        let haystack = "    if foo(bar) as i32 { baz }";
        let pos = find_ignoring_whitespace(haystack, "if foo(bar) as i32").unwrap();
        assert_eq!(&haystack[pos..pos + 4], "if f");
    }

    #[test]
    fn whitespace_insensitive_match_tolerates_inserted_breaks() {
        // prettyplease reflows `*self.state.buffer` across lines, the marker must still match.
        let haystack = "        if *self\n            .state\n            .buffer\n            .offset(loc as isize) as i32";
        let pos = find_ignoring_whitespace(
            haystack,
            "if *self.state.buffer.offset(loc as isize) as i32",
        )
        .expect("reflowed marker should still match");
        assert!(haystack[pos..].starts_with("if *self"));
    }

    #[test]
    fn whitespace_insensitive_match_does_not_split_identifiers() {
        assert!(find_ignoring_whitespace("a b", "ab").is_none());
        assert!(find_ignoring_whitespace("a  b", "a b").is_some());
    }

    #[test]
    fn whitespace_insensitive_match_does_not_split_numbers() {
        assert!(find_ignoring_whitespace("1 2", "12").is_none());
    }

    #[test]
    fn find_marker_end_returns_position_after_match() {
        let haystack = "x && self.state.formatident == 1303 as i32 {";
        let end = find_marker_end(haystack, "&& self.state.formatident == 1303 as i32").unwrap();
        assert!(haystack[end..].trim_start().starts_with('{'));
    }

    #[test]
    fn crate_version_comes_from_the_existing_manifest() {
        let path = std::env::temp_dir().join("mathtex-web2c-cargo-version.toml");
        std::fs::write(&path, "[package]\nname = \"x\"\nversion = \"9.8.7\"\n").unwrap();
        let manifest = cargo_source(&path).expect("manifest with a version");
        assert!(manifest.contains("version = \"9.8.7\""));
        std::fs::write(&path, "[package]\nname = \"x\"\n").unwrap();
        assert!(matches!(
            cargo_source(&path),
            Err(PatchError::MissingCrateVersion { .. })
        ));
    }
}
